import time

def construct():
    start_time = time.time()
    deadline = start_time + 50  # Safety margin for 60s limit
    
    # Generator polynomial for the [17,9,5] cyclic code (unextended QR code of length 17).
    # g(x) = x^8 + x^5 + x^4 + x^3 + 1
    # Integer representation: bit 8, 5, 4, 3, 0 are set.
    g = (1 << 8) | (1 << 5) | (1 << 4) | (1 << 3) | (1 << 0)
    
    # Precompute the 9 basis vectors for the [17,9,5] code.
    # The i-th basis vector corresponds to the codeword generated by message x^i.
    # c_i(x) = x^i * g(x).
    # Since deg(g)=8 and i is in 0..8, max degree is 16, which fits in 17 bits (indices 0..16).
    basis_17 = []
    for i in range(9):
        # Shift g by i positions
        vec = g << i
        basis_17.append(vec)
        
    # Extend each basis vector to length 18 by adding an overall parity bit.
    # The [17,9,5] code has odd minimum distance (5).
    # Extension to [18,9,6] requires adding a parity bit to ensure even weight.
    # Parity bit is placed at index 17.
    basis_18 = []
    for vec in basis_17:
        # Calculate parity of the 17-bit vector
        # Using bin(x).count('1') is fast enough for 9 vectors.
        # Alternatively, use a lookup or bit trick, but 9 is small.
        weight = bin(vec).count('1')
        parity = weight & 1
        ext_vec = vec
        if parity:
            ext_vec |= (1 << 17)
        basis_18.append(ext_vec)
        
    words = []
    
    # Generate all 512 codewords by taking all linear combinations of the 9 basis vectors.
    # Since the code is linear, any codeword is the XOR of a subset of basis vectors.
    # Optimization: Pre-compute the basis list reference and use local variables.
    b = basis_18
    for msg in range(512):
        c_val = 0
        m = msg
        # Unroll or simple loop is fine. 9 iterations is small.
        for i in range(9):
            if m & 1:
                c_val ^= b[i]
            m >>= 1
        words.append(c_val)
        
    return words
